function renderExecutiveFactChart(fact,period="本期"){
  const current=Number(fact?.value||0),prior=Number(fact?.priorValue||0),max=Math.max(1,current,prior),currentHeight=28+current/max*82,priorHeight=28+prior/max*82,baseline=137,yoy=Number(fact?.yoy||0),direction=yoy>=0?"增长":"下降",tone=yoy>=0?"positive":"negative";
  return `<article class="executive-yoy-card ${tone}" role="img" aria-label="${esc(fact?.label)}，${esc(period)}${current.toFixed(1)}万辆，同比同期反算${prior.toFixed(1)}万辆，同比${direction}${Math.abs(yoy*100).toFixed(0)}%"><span>${esc(fact?.label)}</span><strong>同比${direction} ${Math.abs(yoy*100).toFixed(0)}%</strong><svg viewBox="0 0 220 175" aria-hidden="true"><line class="bar-baseline" x1="20" y1="${baseline}" x2="200" y2="${baseline}"/><rect class="current-bar vertical-bar" x="45" y="${baseline-currentHeight}" width="48" height="${currentHeight}" rx="4"/><text class="bar-value" x="69" y="${baseline-currentHeight-7}" text-anchor="middle">${current.toFixed(1)}</text><rect class="prior-bar vertical-bar" x="127" y="${baseline-priorHeight}" width="48" height="${priorHeight}" rx="4"/><text class="bar-value" x="151" y="${baseline-priorHeight-7}" text-anchor="middle">${prior.toFixed(1)}</text><text class="bar-label" x="69" y="158" text-anchor="middle">本期</text><text class="bar-label" x="151" y="158" text-anchor="middle">同比同期</text></svg><small>单位：万辆 · 同期值按同比反算</small></article>`;
}

function renderExecutiveOverview(brief){
  const facts=brief?.facts||[],pulse=executivePulseFrom(brief),source=brief?.source||{period:pulse.period,url:pulse.sourceUrl,label:pulse.sourceLabel},verified=brief?.status==="verified",summary=verified?esc(brief.summary):"三路旗舰模型交叉验证尚未完成，本期摘要暂不发布。",inferences=verified?(brief?.inferences||[]):[],pressure=inferences.filter(item=>item.id!=="penetration_buffer"),buffer=inferences.find(item=>item.id==="penetration_buffer"),refresh=brief?.weeklyRefresh||{};
  const inferenceContent=verified?`<ol class="executive-causal-chain">${pressure.map(item=>`<li><b>${esc(item.title)}</b><small>${esc(item.detail)}</small></li>`).join("")}</ol>${buffer?`<div class="executive-buffer"><span>${esc(buffer.title)}</span><b>${esc(buffer.detail)}</b></div>`:""}`:`<div class="executive-inference-pending">三路旗舰模型交叉验证完成前，MMN模型推论暂不发布。</div>`;
  return `<section class="group-board-section group-executive-section" aria-labelledby="group-executive-title"><header><div><span>01 · EXECUTIVE BRIEF</span><h2 id="group-executive-title">${esc(brief?.headline||"乘用车市场与新能源结构同步变化")}</h2><p>事实数字锁定后，由三路旗舰模型独立验证；只有三路交叉验证一致通过才发布摘要。</p></div><em>${esc(source.period||pulse.period)} · ${esc(refresh.statusLabel||"已发布数据")}</em></header><div class="executive-brief-grid"><article class="executive-thesis ${verified?"verified":"pending"}"><div class="executive-proof-row"><span class="executive-proof-tag">本期一句话</span><span class="executive-review-status ${verified?"verified":"pending"}">${verified?"✓ ":"◷ "}${esc(brief?.statusLabel||"三路旗舰模型交叉验证中 · 暂不发布")}</span></div><h3>${summary}</h3><div class="executive-fact-charts">${facts.filter(fact=>fact.id!=="nev_penetration").map(fact=>renderExecutiveFactChart(fact,source.period)).join("")}</div></article><aside class="executive-causal-card"><div class="executive-card-heading"><span>市场结构推论</span><small class="executive-inference-status ${verified?"verified":"pending"}">${verified?"MMN模型推论 · 已通过三路旗舰模型交叉验证":"MMN模型推论 · 交叉验证中"}</small></div>${inferenceContent}</aside></div><footer class="executive-source-line"><span>事实来源</span><a href="${esc(source.url||pulse.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(source.label||pulse.sourceLabel)}</a><small>自然周 ${esc(source.naturalWeekPeriod||"待发布")} · 批次 ${esc(brief?.batchId||"—")}</small></footer></section>`;
}

 function renderGroupImplications(brief={}){
  const verified=brief?.status==="verified",metaByBrand=Object.fromEntries(groupBrandImplications.map(item=>[item.brand,item])),brandItems=(verified&&brief?.brandImplications?.length?brief.brandImplications:groupBrandImplications).map(item=>({...metaByBrand[item.brand],...item}));
  const selectedBrand=brandItems.some(item=>item.brand===uiState.brand)?uiState.brand:brandItems[0]?.brand||"";
  uiState.brand=selectedBrand;
  const detailsByBrand=Object.fromEntries((verified?brief.brandImplications||[]:[]).map(item=>[item.brand,item]));
  const evidenceLabels={E1:"市场数据",E2:"来源依据",E3:"证据边界"};
  const evidenceRefs=ids=>(ids||[]).map(id=>{const key=String(id||"").toUpperCase(),label=evidenceLabels[key]||"关联证据";return`<span class="consulting-evidence-ref evidence-${esc(key.toLowerCase())}" title="${esc(label)}" aria-label="${esc(`${key} ${label}`)}">${esc(key)}</span>`}).join("");
  const consultingPanel=detail=>{
   const output=detail?.consultingOutput;
   if(!output)return `<div class="executive-inference-pending">三路旗舰模型交叉验证完成前，咨询式策略输出暂不发布。</div>`;
   const findings=(output.keyFindings||[]).map(item=>`<li><span>${esc(String(item.text||"").replace(/\s*\[Evidence:\s*E\d+\]/gi,""))}</span><small>${evidenceRefs(item.evidenceIds)}</small></li>`).join("");
   const evidence=(output.evidence||[]).map(item=>`<li><b>${esc(item.id)}</b><span>${esc(String(item.text||"").replace(new RegExp(`^${item.id}[:：]\\s*`),""))}</span></li>`).join("");
   const actions=(output.actionRecommendation||[]).map(item=>`<li>${esc(String(item).replace(/^-\s*/,""))}</li>`).join("");
   const quality=output.quality||{};
   return `<div class="consulting-output-grid"><article class="consulting-output-section consulting-executive"><header><span>01</span><h4>核心结论</h4></header><p>${esc(output.executiveConclusion)}</p></article><article class="consulting-output-section"><header><span>02</span><h4>关键发现</h4></header><ol class="consulting-findings">${findings}</ol></article><article class="consulting-output-section"><header><span>03</span><h4>数据证据</h4></header><ul class="consulting-evidence-list">${evidence}</ul></article><article class="consulting-output-section"><header><span>04</span><h4>战略影响</h4></header><p>${esc(output.strategicImplication)}</p></article><aside class="consulting-output-section consulting-evidence-legend" aria-label="证据标签颜色说明"><header><span aria-hidden="true">注</span><h4>证据标签说明</h4></header><ul><li>${evidenceRefs(["E1"])}<div><b>市场数据</b><small>锁定的行业与业务数据</small></div></li><li>${evidenceRefs(["E2"])}<div><b>来源依据</b><small>事实来源及统计周期</small></div></li><li>${evidenceRefs(["E3"])}<div><b>证据边界</b><small>策略推断范围与数据缺口</small></div></li></ul></aside><article class="consulting-output-section consulting-actions"><header><span>05</span><h4>行动建议</h4><em class="consulting-quality ${quality.passed&&quality.mecePassed?"passed":"failed"}">${quality.passed&&quality.mecePassed?"✓ MECE 检查已通过":"MECE 检查未通过"}</em></header><ol>${actions}</ol></article></div>`;
  };
  const options=brandItems.map(item=>`<option value="${esc(item.brand)}" ${item.brand===selectedBrand?"selected":""}>${esc(item.brand)}</option>`).join(""),panels=brandItems.map(item=>{const detail=detailsByBrand[item.brand]||{};return`<article class="executive-brand-panel" data-brand-panel="${esc(item.brand)}" ${item.brand===selectedBrand?"":"hidden"}><span>${esc(item.category||"集团重点品牌")}</span><h3>${esc(item.title||item.brand)}</h3>${consultingPanel(detail)}</article>`}).join("");
  return `<section class="group-board-section group-executive-section" aria-labelledby="group-implication-title"><header><div><span>02 · 集团影响</span><h2 id="group-implication-title">把行业变化翻译成上汽的品牌判断</h2><p>全部集团重点品牌与车型使用同一已发布事实批次，按五层金字塔查看结论、证据与行动建议。</p></div><em>${esc(brief?.source?.period||"")} · ${verified?"三路旗舰模型已交叉验证":"交叉验证中 · 暂不发布"}</em></header><div class="executive-impact-layout"><div class="executive-brand-switcher"><label for="group-brand-select"><span>选择品牌</span><select id="group-brand-select" aria-label="选择集团品牌">${options}</select></label><div class="executive-brand-stage" aria-live="polite">${panels}</div></div></div></section>`;
 }

