  return `<section class="group-board-section" aria-labelledby="group-competitive-title"><header><div><span>05 · COMPETITIVE MOMENTUM</span><h2 id="group-competitive-title">E7X 五车传播势能：先声量，后 NSR</h2><p>先用总体声量判断传播规模，再用全网NSR判断这份规模形成正向资产还是负向风险；互动量仅补充活跃度。</p></div><em>${esc(evaluation.source?.period||"")} · 五车同口径</em></header><div class="group-chart-frame group-competitive-frame"><div class="group-decision-order" aria-label="传播势能判断顺序"><span><b>① 总体声量</b> 有没有形成传播规模</span><span><b>② 全网 NSR</b> 规模对应正向还是负向认知</span><span><b>③ 互动量</b> 仅由点大小补充活跃度</span></div><svg class="group-competitive-plot" viewBox="0 0 ${width} ${height}" role="img" aria-label="奥迪E7X与四款竞品传播势能比较"><rect class="quality-zone" x="${left}" y="${top}" width="${right-left}" height="${(bottom-top)*.5}"/><line class="axis" x1="${left}" y1="${bottom}" x2="${right}" y2="${bottom}"/><line class="axis" x1="${left}" y1="${top}" x2="${left}" y2="${bottom}"/><line class="midline" x1="${left}" y1="${bottom-(bottom-top)*.5}" x2="${right}" y2="${bottom-(bottom-top)*.5}"/><text class="zone-label" x="${right-14}" y="${top+22}" text-anchor="end">高口碑区</text><text class="axis-label" x="${(left+right)/2}" y="${height-18}" text-anchor="middle">第一判断：总体声量 →</text><text class="axis-label" transform="translate(30 ${height/2}) rotate(-90)" text-anchor="middle">第二判断：全网 NSR →</text>${points}</svg><div class="group-chart-legend"><span><i class="e7x-star"></i>E7X 本品</span><span><i class="voc-dot"></i>竞品</span><span>本品声量第${own.voiceRank||"—"} · 互动第${own.engagementRank||"—"} · NSR第${own.overallNsrRank||"—"}</span></div></div></section>`;
